package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadAuditLogPort;
import com.example.lending.application.port.out.RecordAuditLogPort;
import com.example.lending.domain.AuditRecord;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class AuditLogPersistenceAdapter implements RecordAuditLogPort, LoadAuditLogPort {

    private final AuditLogJpaRepository auditLogJpaRepository;

    public AuditLogPersistenceAdapter(AuditLogJpaRepository auditLogJpaRepository) {
        this.auditLogJpaRepository = auditLogJpaRepository;
    }

    @Override
    public void record(AuditRecord record) {
        auditLogJpaRepository.save(new AuditLogJpaEntity(record.action(), record.targetId(), record.memberId(),
                record.occurredAt()));
    }

    @Override
    public List<AuditRecord> loadByTargetId(UUID targetId) {
        return auditLogJpaRepository.findByTargetIdOrderBySeqAsc(targetId).stream()
                .map(entity -> new AuditRecord(entity.getAction(), entity.getTargetId(), entity.getMemberId(),
                        entity.getOccurredAt()))
                .toList();
    }
}
