import java.util.UUID;

@Service
@Transactional
public class MemberSuspensionService implements MemberSuspensionUseCase {

    private final LoadMemberPort loadMemberPort;
    private final SaveMemberPort saveMemberPort;
    private final RecordAuditLogPort recordAuditLogPort;

    public MemberSuspensionService(LoadMemberPort loadMemberPort, SaveMemberPort saveMemberPort,
                                   RecordAuditLogPort recordAuditLogPort) {
        this.loadMemberPort = loadMemberPort;
        this.saveMemberPort = saveMemberPort;
        this.recordAuditLogPort = recordAuditLogPort;
    }

    @Override
    public Member suspendMember(UUID memberId) {
        Member member = loadForUpdate(memberId);
        if (member.suspend()) {
            saveMemberPort.saveMember(member);
            record(AuditAction.SUSPEND, member);
        }
        return member;
    }

    @Override
    public Member unsuspendMember(UUID memberId) {
        Member member = loadForUpdate(memberId);
        if (member.unsuspend()) {
            saveMemberPort.saveMember(member);
            record(AuditAction.UNSUSPEND, member);
        }
        return member;
    }

    // 대출 요청과 같은 회원 잠금을 잡아서, 정지 확인과 대출 기록 사이에 상태가 바뀌지 않게 한다.
    private Member loadForUpdate(UUID memberId) {
        return loadMemberPort.loadMemberForUpdate(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
    }

    private void record(AuditAction action, Member member) {
        recordAuditLogPort.record(new AuditRecord(action, member.getId(), member.getId(), Instant.now()));
    }
}
